package com.sobrenaturaldirector.spatial.model;

public final class SpatialBudget {public static final SpatialBudget TECHNICAL_COMPOSITION_DEFAULT=new SpatialBudget(256,64,256,1048576,64,128,64,128);private final int maxWidth,maxHeight,maxDepth,maxNodes,maxAttempts,maxBacktracks,maxExpansionSteps;private final long maxVolume;public SpatialBudget(int width,int height,int depth,long volume,int nodes,int attempts,int backtracks,int expansion){if(width<=0||height<=0||depth<=0||volume<=0||nodes<=0||attempts<=0||backtracks<0||expansion<=0)throw new IllegalArgumentException("invalid spatial budget");maxWidth=width;maxHeight=height;maxDepth=depth;maxVolume=volume;maxNodes=nodes;maxAttempts=attempts;maxBacktracks=backtracks;maxExpansionSteps=expansion;}public int getMaxWidth(){return maxWidth;}public int getMaxHeight(){return maxHeight;}public int getMaxDepth(){return maxDepth;}public long getMaxVolume(){return maxVolume;}public int getMaxNodes(){return maxNodes;}public int getMaxAttempts(){return maxAttempts;}public int getMaxBacktracks(){return maxBacktracks;}public int getMaxExpansionSteps(){return maxExpansionSteps;}}
